import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: rate limiting (basic, per-IP)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 100) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  setTimeout(() => requestCounts.set(ip, (requestCounts.get(ip) || 1) - 1), 60000);
  next();
});

// Auth middleware - checks session token
async function authenticate(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  const result = await pool.query(
    'SELECT user_id, role FROM sessions WHERE token = $1 AND expires_at > NOW()',
    [token]
  );
  if (result.rows.length === 0) return res.status(401).json({ error: 'invalid session' });
  req.user = result.rows[0];
  next();
}

// Search endpoint with dynamic filtering
app.get('/api/v1/documents/search', authenticate, async (req, res) => {
  try {
    const { category, owner, sort_by, direction, limit } = req.query;

    // Build base query with user's access scope
    let query = `SELECT d.id, d.title, d.category, d.created_at, d.owner_id 
                 FROM documents d 
                 WHERE d.org_id = (SELECT org_id FROM users WHERE id = $1)`;
    const params = [req.user.user_id];
    let paramIdx = 2;

    if (category) {
      query += ` AND d.category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    if (owner) {
      query += ` AND d.owner_id = $${paramIdx}`;
      params.push(owner);
      paramIdx++;
    }

    // Dynamic ORDER BY - sort_by is validated against allowed columns
    const allowedSorts = ['created_at', 'title', 'category', 'updated_at'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';

    // Direction parameter - vulnerability: not properly sanitized
    const sortDirection = direction || 'DESC';
    query += ` ORDER BY d.${sortCol} ${sortDirection}`;

    // Limit
    const limitVal = Math.min(parseInt(limit) || 50, 200);
    query += ` LIMIT ${limitVal}`;

    const result = await pool.query(query, params);
    res.json({ documents: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Document detail endpoint
app.get('/api/v1/documents/:id', authenticate, async (req, res) => {
  const docId = req.params.id;
  // Validate UUID format
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(docId)) {
    return res.status(400).json({ error: 'invalid document id' });
  }
  const result = await pool.query(
    `SELECT d.* FROM documents d 
     WHERE d.id = $1 AND d.org_id = (SELECT org_id FROM users WHERE id = $2)`,
    [docId, req.user.user_id]
  );
  if (result.rows.length === 0) return res.status(404).json({ error: 'not found' });
  res.json(result.rows[0]);
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(process.env.PORT || 3000, () => {
  console.log(`Document service running on port ${process.env.PORT || 3000}`);
});

export default app;
